import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp

    if d_opp == 0:
        # Perfectly cooperative so far
        if n >= 6 and n % 19 == 0:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp_at(n - 1)
    last_me = me_at(n - 1)

    # Defection streak at end
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    # Cooperation streak at end
    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n

    # Detect rapid defector: high defection rate
    if d_opp * 2 > n + 1:
        # Mostly defecting - be defensive but probe occasionally
        if streak_d >= 2:
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Endgame exploitation: if opponent likely to cooperate, defect
    remaining = 100 - n
    if remaining <= 4 and coop_rate > 0.55 and streak_d == 0:
        return 'D'

    # Punish long defection runs
    if streak_d >= 3:
        return 'D'
    if streak_d == 2:
        # Punish second defection, but forgive if we caused it (mirroring)
        if last_me == 'D':
            # We also defected -> maybe mutual mistake, forgive
            if rng.random() < 0.55:
                return 'C'
        return 'D'
    if streak_d == 1:
        if coop_rate > 0.75 and streak_c >= 3:
            return 'C'
        if n >= 4 and opp_at(n - 2) == 'C' and opp_at(n - 3) == 'C':
            return 'C'
        if last_me == 'D':
            # We defected, opponent retaliated. Return to C.
            return 'C'
        return 'D'

    # Opponent cooperated last
    if last_me == 'D':
        # We defected, return to cooperation to restore mutual benefit
        return 'C'

    # Detect TFT-like mirror behavior
    if n >= 4:
        mirror = 0
        for j in range(1, n):
            if opp_at(j) == me_at(j - 1):
                mirror += 1
        if mirror >= (n - 1) * 0.7:
            # Mirror: play what opponent likely does - play opponent's last
            # but occasionally defect to exploit predictable cooperation
            if coop_rate >= 0.7 and rng.random() < 0.06 and n < 90:
                return 'D'
            return 'C' if last == 'C' else 'D'

    # Detect alternation
    if n >= 6:
        alt = 0
        for j in range(1, n):
            if opp_at(j) != opp_at(j - 1):
                alt += 1
        if alt >= n - 2:
            if last == 'C':
                return 'D'
            return 'C'

    # If we have defected a lot relative to cooperation and opponent still
    # cooperates, keep exploiting occasionally but not too much
    my_defects = sum(1 for j in range(n) if me_at(j) == 'D')
    if coop_rate >= 0.7:
        if my_defects >= 2 and rng.random() < 0.05 and n < 92:
            return 'D'
        return 'C'

    if coop_rate >= 0.5:
        if rng.random() < 0.08 and n < 90:
            return 'D'
        return 'C'

    # Mixed opponent
    if rng.random() < 0.4:
        return 'C'
    return 'D'
